# -*- coding: utf-8 -*-
from pathlib import Path
import json,collections,html
r=Path(__file__).resolve().parents[1];x=json.loads((r/'references/catalog.json').read_text());groups=collections.Counter(e['category'] for e in x['effects'])
s='# 96 Motion Studies\n\nResearch mechanisms, not claims of original inventions. Run studies.html locally to play each one.\n\n| Category | Count |\n|---|---|\n'
for k,v in groups.items():s+=f'| {k} | {v} |\n'
s+='\n## Indexed previews\n\n| ID | Mechanism | Category | Snapshot | Recorded source |\n|---|---|---|---|---|\n'
for e in x['effects']:
 source=e.get('source','unrecorded');ref=f'[Source]({source})' if source.startswith('http') else source
 s+=f'| {e["id"]} | {e["name"]} | {e["category"]} | [View](gallery/{e["id"]:03d}.{"png" if e["id"]>88 else "svg"}) | {ref} |\n'
s+='\nEarly IDs 1-64 lack complete per-item provenance. No missing authors were invented. See [ATTRIBUTION](../ATTRIBUTION.md) and [LICENSE_SCOPE](../LICENSE_SCOPE.md).\n';(r/'docs/EFFECTS.md').write_text(s)
items=''.join(f'<article><a href="{e["id"]:03d}.{"png" if e["id"]>88 else "svg"}"><img loading="lazy" src="{e["id"]:03d}.{"png" if e["id"]>88 else "svg"}" alt="{html.escape(e["name"])}"></a><small>{e["id"]:03d} / {html.escape(e["category"])}</small><h2>{html.escape(e["name"])}</h2></article>' for e in x['effects'])
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Motion Skill / 96 Studies</title><style>*{box-sizing:border-box}body{background:#141414;color:#fff;font:16px system-ui;margin:0}main{max-width:1440px;margin:auto;padding:48px 24px}h1{font-size:48px;letter-spacing:-.05em}p,small{color:#a8b1bf}input{width:100%;background:#222;color:#fff;border:1px solid #465365;padding:16px;font:inherit;border-radius:12px;margin:24px 0}section{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:20px}article{background:#202228;border-radius:16px;padding:12px}img{width:100%;aspect-ratio:16/9;background:white;border-radius:10px}h2{font-size:18px}small{display:block;margin-top:14px}a{color:#7fc0ff}article[hidden]{display:none}</style><main><p>MOTION SKILL / RESEARCH ARCHIVE</p><h1>96 Studies. 19 Categories.</h1><p>Snapshots of research implementations. No claim of original invention. Run studies.html locally for motion playback.</p><p><a href="../../ATTRIBUTION.md">Attribution</a> / <a href="../../LICENSE_SCOPE.md">License scope</a></p><input aria-label="Search studies" placeholder="Search name, number or category"><section>'''+items+'''</section></main><script>document.querySelector('input').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('article').forEach(a=>a.hidden=!a.textContent.toLowerCase().includes(q))})</script></html>'''
(r/'docs/gallery/index.html').write_text(page)
(r/'verification/counts.json').write_text(json.dumps({'studies':len(x['effects']),'categories':dict(groups),'semantic_renderers':5,'documented_capability_groups':12,'reference_scenes':7,'reference_captions':25,'reference_stock_photo_count':1,'reference_stock_video_seconds':5.4,'historical_compositions_in_catalog':len(x['compositions']),'historical_compositions_available_in_ui':False},ensure_ascii=False,indent=2))
